/**
 * querystring (the npm package, 0.2.1) -> URLSearchParams (JavaScript, native).
 *
 * Why this pair: `querystring` is deprecated, and the usual advice is "use URLSearchParams". The two
 * disagree in many places, and one of them matters for security: the old parser throws on a
 * malformed percent escape, the new one does not. The séance finds seven differences.
 *
 * Note: Node has a built-in module also called "querystring". `import 'querystring'` gets the
 * built-in, never the npm package. The séance loads the npm package as `querystring/`.
 */

import type { KnownDifference, SeanceBundle, SeanceFile } from '../../types.js';
import { callsNote, jsProjectCalls } from '../examples.js';
import { renderReadme } from '../readme.js';
import { makeBundle, type Mutant, type Recipe, type RecipeContext } from '../recipe.js';
import { depOfContext, oldVersionsFor } from '../versions.js';

const DIR = 'seance/querystring';

export const QUERYSTRING_KNOWN: KnownDifference[] = [
  {
    input: 'parse("a=%zz")',
    old: 'throws URIError (URI malformed)',
    naive: '{ a: "%zz" }',
    handled:
      'Accepted: the replacement does not throw. A request with a bad escape no longer crashes the caller.',
  },
  {
    input: 'parse("&&a=1&&")',
    old: '{ "": ["", "", "", ""], a: "1" } (empty pairs become an empty key)',
    naive: '{ a: "1" }',
    handled: 'Accepted: empty pairs are skipped.',
  },
  {
    input: 'parse("?a=1")',
    old: '{ "?a": "1" } (the ? is part of the key)',
    naive: '{ a: "1" } (a leading ? is dropped)',
    handled: 'Reproduced: the replacement keeps the leading ? in the key.',
  },
  {
    input: 'parse(1001 pairs)',
    old: 'keeps only the first 1000 pairs',
    naive: 'keeps all 1001',
    handled: 'Accepted: no limit. Cap the input length yourself if you parse untrusted text.',
  },
  {
    input: 'stringify({ a: "x y" })',
    old: '"a=x%20y"',
    naive: '"a=x+y"',
    handled: 'Reproduced: the replacement uses encodeURIComponent, like the old package.',
  },
  {
    input: 'stringify({ a: null })',
    old: '"a="',
    naive: '"a=null"',
    handled: 'Reproduced: values that are not strings, finite numbers or booleans become empty.',
  },
  {
    input: 'stringify({ a: "!\'()*~" })',
    old: '"a=!\'()*~"',
    naive: '"a=%21%27%28%29*%7E"',
    handled: 'Reproduced: the replacement uses encodeURIComponent.',
  },
];

function replacementSource(): string {
  return [
    '// Replacement for the npm package "querystring". Generated by Necromancer (recipe "querystring").',
    "// Dependency-free. Parsing uses URLSearchParams; stringify keeps the old package's escaping.",
    '//',
    '// Not reproduced, on purpose (see README.md): a malformed %-escape no longer throws, empty',
    '// pairs are skipped, and there is no limit of 1000 pairs.',
    '',
    'export function parse(str) {',
    '  const out = {};',
    "  if (typeof str !== 'string' || str.length === 0) return out;",
    "  // The old package keeps a leading '?' in the first key; URLSearchParams drops it.",
    "  for (const [key, value] of new URLSearchParams('?' + str)) {",
    "    if (key === '__proto__') continue; // the old package could not store this key either",
    '    if (!Object.prototype.hasOwnProperty.call(out, key)) out[key] = value;',
    '    else if (Array.isArray(out[key])) out[key].push(value);',
    '    else out[key] = [out[key], value];',
    '  }',
    '  return out;',
    '}',
    '',
    'function primitive(v) {',
    '  switch (typeof v) {',
    "    case 'string':",
    '      return v;',
    "    case 'boolean':",
    "      return v ? 'true' : 'false';",
    "    case 'number':",
    "      return Number.isFinite(v) ? String(v) : '';",
    '    default:',
    "      return '';",
    '  }',
    '}',
    '',
    "export function stringify(obj, sep = '&', eq = '=') {",
    "  if (obj === null || typeof obj !== 'object') return '';",
    '  return Object.keys(obj)',
    '    .map((key) => {',
    '      const prefix = encodeURIComponent(primitive(key)) + eq;',
    '      const value = obj[key];',
    '      if (Array.isArray(value)) return value.map((v) => prefix + encodeURIComponent(primitive(v))).join(sep);',
    '      return prefix + encodeURIComponent(primitive(value));',
    '    })',
    '    .filter(Boolean)',
    '    .join(sep);',
    '}',
    '',
    'export const decode = parse;',
    'export const encode = stringify;',
    '',
  ].join('\n');
}

function testSource(parseCalls: string[], stringifyCalls: string[]): string {
  return [
    '// Séance: querystring (npm) -> URLSearchParams. Generated by Necromancer (recipe "querystring").',
    '// Run: npx vitest run seance/querystring',
    '//',
    '// Compared: the object parse returns (as ordered key/values-list entries) or the string',
    '// stringify returns, or the error class when the call throws (never the message).',
    '// Not compared (accepted differences, pinned by the last tests): malformed %-escapes, empty',
    '// pairs, and inputs of more than 1000 pairs.',
    "import { createRequire } from 'node:module';",
    "import { describe, it, expect } from 'vitest';",
    "import fc from 'fast-check';",
    "import * as replacement from './replacement.mjs';",
    '',
    '// "querystring/" with the slash is the npm package; "querystring" alone is the Node built-in.',
    "const old = createRequire(import.meta.url)('querystring/');",
    '',
    'const outcome = (fn, args) => {',
    '  try {',
    '    return { ok: true, value: fn(...args) };',
    '  } catch (e) {',
    '    return { ok: false, error: e && e.constructor ? e.constructor.name : typeof e };',
    '  }',
    '};',
    '// Objects as ordered entries; every value as a list, so "a" and ["a"] are told apart by length.',
    'const entries = (o) => (o && typeof o === "object" ? Object.entries(o).map(([k, v]) => [k, Array.isArray(v) ? v : [v]]) : o);',
    'const parseOutcome = (fn, args) => { const r = outcome(fn, args); return r.ok ? { ok: true, value: entries(r.value) } : r; };',
    '',
    '// What a reader would try first.',
    'const naiveParse = (s) => { const o = {}; for (const [k, v] of new URLSearchParams(s)) { if (k in o) o[k] = [].concat(o[k], v); else o[k] = v; } return o; };',
    'const naiveStringify = (o) => new URLSearchParams(o).toString();',
    '',
    '// Generators.',
    'const text = fc.oneof(fc.string({ maxLength: 6 }), fc.string({ unit: "binary", maxLength: 4 }), fc.constantFrom("", " ", "+", "=", "&", "%", "a b", "\\u00e9", "\\ud83d\\ude00", "~", "!\'()*"));',
    '// A well-formed query string: encoded pairs, "+" for spaces, optional values.',
    'const pair = fc.tuple(text, fc.option(text, { nil: undefined })).map(([k, v]) => {',
    '  const enc = (s) => encodeURIComponent(s).replace(/%20/g, "+");',
    '  return v === undefined ? enc(k) : enc(k) + "=" + enc(v);',
    '});',
    'const wellFormed = fc.array(pair, { minLength: 1, maxLength: 6 }).map((p) => p.join("&")).filter((q) => !q.split("&").some((s) => s === ""));',
    'const hasLoneSurrogate = (s) => /[\\ud800-\\udbff](?![\\udc00-\\udfff])|(?<![\\ud800-\\udbff])[\\udc00-\\udfff]/.test(s);',
    '// Raw text from a small alphabet that often makes odd but valid queries; escapes are skipped.',
    'const raw = fc.stringMatching(/^[a-c0-9=&+?;\\-_.~ ]{0,12}$/).filter((q) => q === "" || !q.split("&").some((s) => s === ""));',
    '',
    'const scalar = fc.oneof(text, fc.integer(), fc.double(), fc.boolean(), fc.constantFrom(null, undefined, NaN, Infinity));',
    'const value = fc.oneof(scalar, fc.array(scalar, { maxLength: 3 }), fc.constantFrom({}, { x: 1 }, () => 1));',
    'const object = fc.dictionary(text, value, { maxKeys: 5 });',
    '',
    ...parseCalls,
    ...stringifyCalls,
    '',
    "describe('seance: querystring -> URLSearchParams', () => {",
    "  it('parse: the replacement answers like querystring.parse for well-formed queries', () => {",
    '    fc.assert(',
    '      fc.property(fc.oneof(wellFormed, raw), (q) => {',
    '        fc.pre(!hasLoneSurrogate(q));',
    '        expect(parseOutcome(replacement.parse, [q])).toEqual(parseOutcome(old.parse, [q]));',
    '      }),',
    '      { numRuns: 1500 },',
    '    );',
    '  });',
    '',
    "  it('parse: the replacement never throws on any text, including what makes querystring throw', () => {",
    '    fc.assert(',
    '      fc.property(fc.oneof(fc.string(), fc.string({ unit: "binary" })), (q) => {',
    '        fc.pre(!hasLoneSurrogate(q));',
    '        const r = outcome(replacement.parse, [q]);',
    '        expect(r.ok).toBe(true);',
    '        const o = outcome(old.parse, [q]);',
    '        // Where the old package does answer and the text has no empty pair, the answers match.',
    '        if (o.ok && !q.split("&").some((s) => s === "") ) expect(parseOutcome(replacement.parse, [q])).toEqual(parseOutcome(old.parse, [q]));',
    '        // Where it throws, it throws URIError (a malformed escape), nothing else.',
    '        if (!o.ok) expect(o.error).toBe("URIError");',
    '      }),',
    '      { numRuns: 1500 },',
    '    );',
    '  });',
    '',
    "  it('stringify: the replacement answers like querystring.stringify', () => {",
    '    fc.assert(',
    '      fc.property(object, (o) => {',
    '        expect(outcome(replacement.stringify, [o])).toEqual(outcome(old.stringify, [o]));',
    '      }),',
    '      { numRuns: 1500 },',
    '    );',
    '  });',
    '',
    "  it('stringify: non-objects and custom separators answer alike', () => {",
    '    fc.assert(',
    '      fc.property(fc.oneof(fc.string(), fc.integer(), fc.constantFrom(null, undefined)), fc.constantFrom("&", ";", "::"), fc.constantFrom("=", ":"), (x, sep, eq) => {',
    '        expect(outcome(replacement.stringify, [x, sep, eq])).toEqual(outcome(old.stringify, [x, sep, eq]));',
    '      }),',
    '    );',
    '    fc.assert(',
    '      fc.property(object, (o) => {',
    '        expect(outcome(replacement.stringify, [o, ";", ":"])).toEqual(outcome(old.stringify, [o, ";", ":"]));',
    '      }),',
    '    );',
    '  });',
    '',
    "  it('stringify then parse gives the same object with both implementations', () => {",
    '    fc.assert(',
    '      fc.property(fc.dictionary(text, fc.oneof(text, fc.array(text, { minLength: 1, maxLength: 3 })), { maxKeys: 4 }), (o) => {',
    '        fc.pre(!Object.keys(o).concat(Object.values(o).flat()).some(hasLoneSurrogate) && !("__proto__" in o && Object.keys(o).includes("__proto__")));',
    '        const a = old.parse(old.stringify(o));',
    '        const b = replacement.parse(replacement.stringify(o));',
    '        expect(entries(b)).toEqual(entries(a));',
    '      }),',
    '    );',
    '  });',
    '',
    "  it('the replacement answers like querystring on the calls this project makes', () => {",
    '    for (const args of projectParse) expect(parseOutcome(replacement.parse, args), JSON.stringify(args)).toEqual(parseOutcome(old.parse, args));',
    '    for (const args of projectStringify) expect(outcome(replacement.stringify, args), JSON.stringify(args)).toEqual(outcome(old.stringify, args));',
    '  });',
    '',
    '  // The naive replacement (URLSearchParams used directly) differs on these inputs.',
    "  it('the naive URLSearchParams differs from querystring on the known inputs', () => {",
    '    for (const q of ["?a=1"]) expect(parseOutcome(naiveParse, [q]), q).not.toEqual(parseOutcome(old.parse, [q]));',
    '    for (const o of [{ a: "x y" }, { a: null }, { a: "!\'()*~" }, { a: [1, 2] }]) {',
    '      expect(outcome(naiveStringify, [o]), JSON.stringify(o)).not.toEqual(outcome(old.stringify, [o]));',
    '      expect(outcome(replacement.stringify, [o]), JSON.stringify(o)).toEqual(outcome(old.stringify, [o]));',
    '    }',
    '    expect(parseOutcome(replacement.parse, ["?a=1"])).toEqual(parseOutcome(old.parse, ["?a=1"]));',
    '  });',
    '',
    "  it('accepted differences, pinned on both sides: if either side changes, review the migration', () => {",
    '    // a malformed escape: the old package throws, the replacement answers',
    '    expect(outcome(old.parse, ["a=%zz"])).toEqual({ ok: false, error: "URIError" });',
    '    expect(replacement.parse("a=%zz")).toEqual({ a: "%zz" });',
    '    // empty pairs',
    '    expect(entries(old.parse("&&a=1&&"))).toEqual([["", ["", "", "", ""]], ["a", ["1"]]]);',
    '    expect(entries(replacement.parse("&&a=1&&"))).toEqual([["a", ["1"]]]);',
    '    // at most 1000 pairs',
    '    const many = Array.from({ length: 1001 }, (_, i) => "k" + i + "=v").join("&");',
    '    expect(Object.keys(old.parse(many))).toHaveLength(1000);',
    '    expect(Object.keys(replacement.parse(many))).toHaveLength(1001);',
    '  });',
    '});',
    '',
  ].join('\n');
}

function build(ctx: RecipeContext): SeanceBundle {
  const pickParse = (m: string): boolean => m === 'parse' || m === 'decode';
  const pickStringify = (m: string): boolean => m === 'stringify' || m === 'encode';
  const files: SeanceFile[] = [
    {
      path: `${DIR}/seance.test.mjs`,
      content: testSource(
        jsProjectCalls(ctx.usage, pickParse, 'projectParse'),
        jsProjectCalls(ctx.usage, pickStringify, 'projectStringify'),
      ),
      role: 'test',
    },
    { path: `${DIR}/replacement.mjs`, content: replacementSource(), role: 'replacement' },
  ];
  const compares = [
    'parse: the object returned, as ordered [key, [values]] entries. stringify: the returned string. Where a call throws: the error class, never the message.',
    'Inputs: well-formed query strings with encoded unicode, "+" for spaces and missing values; small raw strings; objects with strings, numbers, booleans, null, undefined, arrays and nested objects as values; custom separators.',
    'Not compared, but pinned in the last test: malformed %-escapes, empty pairs, more than 1000 pairs.',
    `parse: ${callsNote(ctx.usage, pickParse)}`,
    `stringify: ${callsNote(ctx.usage, pickStringify)}`,
  ];
  const install = ['npm install --save-dev vitest fast-check'];
  const oldVersions = oldVersionsFor('querystring', depOfContext(ctx));
  compares.push(`Versions: ${oldVersions.note}`);
  const run = 'npx vitest run seance/querystring';
  files.push({
    path: `${DIR}/README.md`,
    role: 'readme',
    content: renderReadme({
      title: 'querystring to URLSearchParams',
      recipe: 'querystring',
      files: [
        { path: `${DIR}/seance.test.mjs`, what: 'the differential property test' },
        {
          path: `${DIR}/replacement.mjs`,
          what: 'parse (URLSearchParams) and stringify (encodeURIComponent) with the old answers',
        },
      ],
      install,
      run,
      compares,
      known: QUERYSTRING_KNOWN,
      versions: oldVersions.note,
      notes: [
        'Node has a built-in module named querystring. import "querystring" gets the built-in; the séance loads the npm package with require("querystring/").',
      ],
    }),
  });
  return makeBundle({
    language: 'javascript',
    recipe: 'querystring',
    title: 'querystring to URLSearchParams',
    files,
    install,
    run,
    compares,
    knownDifferences: QUERYSTRING_KNOWN,
    members: ['parse', 'stringify', 'decode', 'encode'],
    oldVersions,
  });
}

function mutants(): Mutant[] {
  const path = `${DIR}/replacement.mjs`;
  const base = replacementSource();
  return [
    {
      id: 'naive-URLSearchParams',
      description: 'uses URLSearchParams for both directions (the obvious migration)',
      files: [
        {
          path,
          role: 'replacement',
          content: [
            'export function parse(s) { const o = {}; for (const [k, v] of new URLSearchParams(s)) { if (k in o) o[k] = [].concat(o[k], v); else o[k] = v; } return o; }',
            'export function stringify(o) { return new URLSearchParams(o).toString(); }',
            'export const decode = parse; export const encode = stringify;',
            '',
          ].join('\n'),
        },
      ],
    },
    {
      id: 'drops-repeated-keys',
      description: 'keeps only the last value of a repeated key',
      files: [
        {
          path,
          role: 'replacement',
          content: base.replace(
            'else if (Array.isArray(out[key])) out[key].push(value);\n    else out[key] = [out[key], value];',
            'else out[key] = value;',
          ),
        },
      ],
    },
  ];
}

export const querystringRecipe: Recipe = {
  id: 'querystring',
  language: 'javascript',
  ecosystem: 'npm',
  old: 'querystring',
  successors: ['URLSearchParams'],
  why: 'A deprecated package with a native successor that is not equivalent; the difference includes a crash on malformed input.',
  build,
  mutants,
};
